#nullable enable

using System;
using System.Text.RegularExpressions;
using Campground.Shared.Security;
using Microsoft.AspNetCore.Http;

namespace Campground.Shared.Contracts
{
    /// <summary>What kind of device a Jellyfin app is running on (issue #31 item 2).</summary>
    internal enum ClientKind
    {
        /// <summary>Not recognised. Each plugin decides what this means (FieldGuide: a computer; CleanStream: no
        /// remembered pick). Never fold it into another kind here.</summary>
        Unknown,

        /// <summary>A television, a TV box, or a cast receiver.</summary>
        Tv,

        /// <summary>A phone or a tablet.</summary>
        PhoneOrTablet,

        /// <summary>A browser or a desktop app on a computer.</summary>
        Computer,
    }

    /// <summary>
    /// One table from a Jellyfin app's <c>Client</c> (and, for apps that run anywhere, its <c>DeviceName</c>) to a
    /// <see cref="ClientKind"/>. FieldGuide's media-type grid (F45) and CleanStream's remembered picks (decision D)
    /// use the same table, so the two plugins agree on what a TV is.
    /// <para>
    /// The <c>Client</c> strings were read from each app's source on 2026-11-13 (see the tests). Real servers can send
    /// others, so FieldGuide's test C1 and CleanStream's probe check them live. Add rows, never change one: a plugin
    /// may have stored a choice per kind.
    /// </para>
    /// <para>
    /// <c>Client</c> and <c>DeviceName</c> come from the app. They name a device for tidiness; they prove nothing
    /// (<see cref="AuthorizationHeader"/>). Use the kind for display choices only, never for access.
    /// </para>
    /// </summary>
    internal static class ClientKinds
    {
        // Apps whose Client says which kind they are. Checked in order, so "Android TV" comes before "Android".
        private static readonly (string Contains, ClientKind Kind)[] ByClient =
        {
            ("android tv", ClientKind.Tv),
            ("roku", ClientKind.Tv),
            ("webos", ClientKind.Tv),
            ("tizen", ClientKind.Tv),
            ("tvos", ClientKind.Tv),
            ("chromecast", ClientKind.Tv),
            ("kodi", ClientKind.Tv),
            ("jellycon", ClientKind.Tv),
            ("xbox", ClientKind.Tv),
            ("wholphin", ClientKind.Tv),
            ("moonfin", ClientKind.Tv),
            ("swiftfin ios", ClientKind.PhoneOrTablet),
            ("swiftfin ipados", ClientKind.PhoneOrTablet),
            ("jellyfin for android", ClientKind.PhoneOrTablet),
            ("findroid", ClientKind.PhoneOrTablet),
            ("streamyfin", ClientKind.PhoneOrTablet),
        };

        // Apps that run on any kind of device. Their DeviceName decides, and with no clue they are a computer
        // (Infuse, which runs on Apple TV and iPhone alike, stays Unknown).
        private static readonly (string Contains, ClientKind Default)[] RunsAnywhere =
        {
            ("jellyfin web", ClientKind.Computer),
            ("jellyfin media player", ClientKind.Computer),
            ("jellyfin desktop", ClientKind.Computer),
            ("infuse", ClientKind.Unknown),
        };

        // "TV" or a TV maker's word as a whole word; "TVTuner" doesn't count.
        private static readonly Regex TvDevice = new(
            @"\b(tv|smart ?tv|apple tv|android tv|bravia|shield|fire ?tv|chromecast)\b",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Compiled);

        private static readonly Regex PhoneDevice = new(
            @"\b(iphone|ipad|ipod|android phone|pixel|galaxy|phone|tablet)\b",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Compiled);

        /// <summary>The kind of device <paramref name="client"/> runs on.</summary>
        internal static ClientKind Classify(string? client, string? deviceName)
        {
            if (string.IsNullOrWhiteSpace(client))
            {
                return ClientKind.Unknown;
            }

            foreach (var (contains, kind) in ByClient)
            {
                if (client.Contains(contains, StringComparison.OrdinalIgnoreCase))
                {
                    return kind;
                }
            }

            foreach (var (contains, fallback) in RunsAnywhere)
            {
                if (client.Contains(contains, StringComparison.OrdinalIgnoreCase))
                {
                    if (!string.IsNullOrWhiteSpace(deviceName))
                    {
                        if (TvDevice.IsMatch(deviceName))
                        {
                            return ClientKind.Tv;
                        }

                        if (PhoneDevice.IsMatch(deviceName))
                        {
                            return ClientKind.PhoneOrTablet;
                        }
                    }

                    return fallback;
                }
            }

            return ClientKind.Unknown;
        }

        /// <summary>The kind for a request, from <c>Client</c> and <c>Device</c> in its authorization header. Only call
        /// it on routes that use the answer (<see cref="AuthorizationHeader"/>'s cost note).</summary>
        internal static ClientKind Classify(HttpRequest request)
            => Classify(AuthorizationHeader.Parameter(request, "Client"), AuthorizationHeader.Parameter(request, "Device"));
    }
}
